contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function taking inputs that drive C.transfer
    function run(address from, address caddress, address[] memory _tos, uint[] memory v) public payable {
        // require non-empty tos as contract C.requires it
        require(_tos.length > 0);
        // call C.transfer and capture whether it reverts and its return value
        bool reverted;
        bool ret;
        try c.transfer(from, caddress, _tos, v) returns (bool r) {
            reverted = false;
            ret = r;
        } catch {
            reverted = true;
            ret = false;
        }

        // The general rule: if the call did not revert then it must have returned true.
        // This links non-reversion to successful boolean return value from transfer.
        assert(reverted || ret == true);
    }

    receive() external payable {}
}

